function roomSummary(runtime:SqliteHearMeOutRoomMediaRuntime,principal:HearMeOutPrincipalV1,room:HearMeOutRoomV1){const members=runtime.listMembers(principal.tenantId,room.roomId);let activeCount=0;try{activeCount=new Set(runtime.listActivePresence(principal.tenantId,room.roomId).map(item=>item.userId)).size}catch{}return{...room,member:members.some(item=>item.userId===principal.userId),memberCount:members.length,activeCount};}
async function resolvePrincipal(request:IncomingMessage,spmtOrigin:string):Promise<HearMeOutPrincipalV1>{const headers:Record<string,string>={accept:"application/json","x-spmt-app":"hearmeout"};if(request.headers.cookie)headers.cookie=request.headers.cookie;const response=await fetch(`${spmtOrigin}/v1/session`,{headers,redirect:"manual"});if(!response.ok)throw new Error("Sign in to SpaceMountain before using Hear Me Out");const value=await response.json() as Record<string,unknown>,userId=typeof value.actorId==="string"?value.actorId:"",tenantId=Array.isArray(value.tenantIds)&&typeof value.tenantIds[0]==="string"?value.tenantIds[0]:"",scopes=Array.isArray(value.scopes)?value.scopes.filter((item):item is string=>typeof item==="string"):[];if(!userId||!tenantId)throw new Error("SPMT session has no user or tenant");const admin=scopes.some(scope=>scope==="*"||scope==="admin"||scope.startsWith("admin:")||scope.endsWith(":any")),displayName=typeof value.displayName==="string"&&value.displayName.trim()?value.displayName.trim():typeof value.username==="string"&&value.username.trim()?value.username.trim():userId;return{tenantId,userId,displayName,roles:admin?["admin"]:["member"]};}
function makeRoomId(name:string){const slug=name.toLowerCase().normalize("NFKD").replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"").slice(0,48)||"room";return`${slug}-${Date.now().toString(36)}-${randomBytes(3).toString("hex")}`;}
