function applyPageHeaders(response:ServerResponse){response.setHeader("content-security-policy","default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; media-src 'self' https: http: blob:; base-uri 'none'; form-action 'self'; frame-ancestors 'self'; object-src 'none'");response.setHeader("permissions-policy","camera=(), microphone=(self), geolocation=(), payment=(), usb=(), serial=(), bluetooth=()");response.setHeader("referrer-policy","no-referrer");response.setHeader("x-frame-options","SAMEORIGIN");}
